{"explanation":"A line of best fit (ordinary least squares regression) finds the unique straight line y = mx + b that minimizes the sum of squared vertical residuals between the line and the data points. Drag any yellow point to move it; the slope m, intercept b, and the red fit line update instantly from the closed-form formulas m = (nΣxy − ΣxΣy)/(nΣx² − (Σx)²) and b = (Σy − mΣx)/n.","manimCode":"const axes = new Axes({
  xRange: [0, 10, 2],
  yRange: [0, 10, 2],
  xLength: 9,
  yLength: 5.5,
  tips: true
});
axes.shift(scaleVec(0.2, DOWN));

const xLabel = new Text({ text: 'x', fontSize: 22, color: GRAY });
const yLabel = new Text({ text: 'y', fontSize: 22, color: GRAY });
xLabel.nextTo(axes, DOWN);
xLabel.shift(scaleVec(4, RIGHT));
yLabel.nextTo(axes, LEFT);
yLabel.shift(scaleVec(2.2, UP));

const title = new Text({ text: 'Line of Best Fit — drag the points', fontSize: 28, color: WHITE });
title.moveTo([0, 3.5, 0]);

const data = [
  { x: 1.2, y: 2.0 },
  { x: 2.5, y: 3.4 },
  { x: 3.8, y: 3.1 },
  { x: 5.0, y: 5.6 },
  { x: 6.2, y: 5.2 },
  { x: 7.5, y: 7.8 },
  { x: 8.8, y: 8.1 }
];

function worldToAxes(pt) {
  const o = axes.c2p(0, 0);
  const ux = axes.c2p(1, 0);
  const uy = axes.c2p(0, 1);
  const dx = ux[0] - o[0];
  const dy = uy[1] - o[1];
  return [(pt[0] - o[0]) / dx, (pt[1] - o[1]) / dy];
}

function leastSquares(pts) {
  const n = pts.length;
  let sx = 0, sy = 0, sxy = 0, sxx = 0;
  for (const p of pts) {
    sx += p.x; sy += p.y; sxy += p.x * p.y; sxx += p.x * p.x;
  }
  const den = n * sxx - sx * sx;
  if (Math.abs(den) < 1e-9) return { m: 0, b: sy / n };
  const m = (n * sxy - sx * sy) / den;
  const b = (sy - m * sx) / n;
  return { m, b };
}

function lineEndpoints(m, b) {
  const x0 = 0, x1 = 10;
  let y0 = m * x0 + b;
  let y1 = m * x1 + b;
  // clip roughly to visible y-range for a clean look
  y0 = Math.max(-0.5, Math.min(10.5, y0));
  y1 = Math.max(-0.5, Math.min(10.5, y1));
  return [axes.c2p(x0, y0), axes.c2p(x1, y1)];
}

let { m, b } = leastSquares(data);
const fitLine = new Polygon({
  vertices: lineEndpoints(m, b),
  color: RED
});
fitLine.setStrokeWidth(4).setFillOpacity(0);

const dots = data.map((p) => {
  const d = new Dot({ point: axes.c2p(p.x, p.y), color: YELLOW });
  d.setFill(YELLOW, 1);
  return d;
});

function formatEq(mVal, bVal) {
  const ms = (mVal >= 0 ? '' : '-') + Math.abs(mVal).toFixed(2);
  const bs = (bVal >= 0 ? ' + ' : ' - ') + Math.abs(bVal).toFixed(2);
  return 'y = ' + ms + 'x' + bs;
}

let eqLabel = new Text({ text: formatEq(m, b), fontSize: 26, color: RED_A });
eqLabel.moveTo([0, -3.4, 0]);

function updateFit() {
  const res = leastSquares(data);
  m = res.m;
  b = res.b;
  fitLine.setVertices(lineEndpoints(m, b));
  const pos = eqLabel.getCenter();
  scene.remove(eqLabel);
  eqLabel = new Text({ text: formatEq(m, b), fontSize: 26, color: RED_A });
  eqLabel.moveTo(pos);
  scene.add(eqLabel);
}

scene.add(axes, xLabel, yLabel, title, fitLine, eqLabel);
for (const d of dots) scene.add(d);

await scene.play(new AnimationGroup([
  new Create(axes),
  new FadeIn(title),
  new FadeIn(xLabel),
  new FadeIn(yLabel)
]));
await scene.play(new AnimationGroup(dots.map((d) => new FadeIn(d))));
await scene.play(new Create(fitLine));
await scene.play(new FadeIn(eqLabel));

dots.forEach((d, i) => {
  makeHoverable(d, scene, { hoverScale: 1.35, hoverColor: ORANGE });
  makeDraggable(d, scene, {
    onDrag: (mob) => {
      let [ax, ay] = worldToAxes(mob.getCenter());
      ax = Math.max(0, Math.min(10, ax));
      ay = Math.max(0, Math.min(10, ay));
      data[i].x = ax;
      data[i].y = ay;
      mob.moveTo(axes.c2p(ax, ay));
      updateFit();
    }
  });
});

const controls = new Controls(scene, { position: 'top-right', width: 200 });
controls.addButton({
  label: 'Reset points',
  onClick: () => {
    const initial = [
      [1.2, 2.0], [2.5, 3.4], [3.8, 3.1], [5.0, 5.6],
      [6.2, 5.2], [7.5, 7.8], [8.8, 8.1]
    ];
    initial.forEach((xy, i) => {
      data[i].x = xy[0];
      data[i].y = xy[1];
      dots[i].moveTo(axes.c2p(xy[0], xy[1]));
    });
    updateFit();
  }
});

await scene.wait(999999);"}

